        """Launch a draft campaign. Returns a preview first. A person approves before anything sends.

        `POST /v1/launch_campaign`

        With dry_run=True the result is the call's plan and nothing is looked up,
        reserved or charged. The return type follows the flag.

        Args:
            supersedes: The confirmation_token of the approval this request replaces.
                Needed only when that approval was already approved and hasn't started yet;
                one still waiting for a decision is replaced automatically. Only where
                Layrcake runs approved actions itself (the result's approval block says
                execution: server); anywhere else it is refused. A dry run doesn't check it,
                so it refuses it: send it on the call itself.
            first_send_not_before: The earliest the first emails may go out (ISO 8601).
                They start at the first sending-window opening at least 60 minutes after a
                person approves, and not before this time. It can't be later than the
                approval's lifetime after this request (7 days by default); a later time is
                refused. Only where Layrcake runs approved actions itself (the result's
                approval block says execution: server); anywhere else it is refused. A dry
                run doesn't check it, so it refuses it: send it on the call itself.
            idempotency_key: Sent as the Idempotency-Key header. If omitted, the SDK
                generates one and reuses it on every automatic retry of this call.
        """
        return self._transport.request(
            _ops.LAUNCH_CAMPAIGN,
            body={
                "campaign_id": campaign_id,
                "confirmation_token": confirmation_token,
                "daily_send_limit": daily_send_limit,
                "dry_run": dry_run,
                "supersedes": supersedes,
                "first_send_not_before": first_send_not_before,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
            extra_headers=extra_headers,
            extra_query=extra_query,
            timeout=timeout,
        )

