    async def export_trail_csv(
        self,
        *,
        campaign_id: Union[str, NotGiven] = NOT_GIVEN,
        email: Union[str, NotGiven] = NOT_GIVEN,
        kind: Union[List[Literal["verify_verdict", "admitted", "removed", "capped", "provider_correlated", "queued", "launch_requested", "launched", "launch_failed", "approval_requested", "approved", "declined", "consumed", "expired", "reply", "bounce", "stop", "complaint", "pause_requested", "paused", "resume_requested", "resumed", "spend_threshold_crossed", "dnc_added", "dnc_loosened", "dnc_loosen_cancelled", "reply_sent", "reply_failed", "approval_superseded", "completed", "approval_held", "approval_undone", "approval_cancelled", "approval_failed", "approval_change_requested", "approval_revised", "approval_reply_myself", "tool_action", "lead_status"]], NotGiven] = NOT_GIVEN,
        since: Union[str, NotGiven] = NOT_GIVEN,
        until: Union[str, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, Any]] = None,
        timeout: Union[float, httpx.Timeout, NotGiven, None] = NOT_GIVEN,
    ) -> LayrcakeResponse[ExportTrailCsvResult]:
        """Complete bounded trail CSV.

        Requires trail:read and the pilot gate; free.

        One snapshot; at most 10,000 events, 1,000 approvals, 5,000 decisions, 10 MiB
        and five seconds. No partial downloads. Identity/access changes require
        regeneration. Private no-store attachment. CSV cells are quoted after prefixing
        an apostrophe to formula-leading text or leading tab/CR/LF; compare parsed cells
        after that transform, retaining ISO timestamps. Proof omits recipient identities
        and content; supporting settlement events remain separate from directly
        campaign-filtered events.

        `GET /v1/trail/export.csv`

        Args:
            email: Resolved to your own subject; never echoed back except on retained
                events.
            kind: Repeatable or comma-separated.
        """
        return await self._transport.request(
            _ops.EXPORT_TRAIL_CSV,
            query={
                "campaign_id": campaign_id,
                "email": email,
                "kind": kind,
                "since": since,
                "until": until,
            },
            extra_headers=extra_headers,
            extra_query=extra_query,
            timeout=timeout,
        )

