    async def tighten_key_policy(
        self,
        key_id: str,
        *,
        name: Union[str, NotGiven] = NOT_GIVEN,
        scopes: Union[Sequence[Literal["data:read", "llm", "campaign:write", "campaign:launch", "assets:purchase", "usage:read", "reply:send", "control:manage", "trail:read"]], NotGiven] = NOT_GIVEN,
        monthly_spend_cap: Union[Optional[str], NotGiven] = NOT_GIVEN,
        autonomous_external_actions: Union[Literal[False], NotGiven] = NOT_GIVEN,
        autonomous_action_limits: Union[TightenKeyPolicyParamsAutonomousActionLimits, NotGiven] = NOT_GIVEN,
        premium_offers: Union[Literal["ask", "never"], NotGiven] = NOT_GIVEN,
        premium_max_credits_per_call: Union[str, NotGiven] = NOT_GIVEN,
        data_route: Union[Optional[Literal["balanced", "cheapest", "broadest", "fastest"]], NotGiven] = NOT_GIVEN,
        idempotency_key: Union[str, NotGiven] = NOT_GIVEN,
        extra_headers: Optional[Mapping[str, str]] = None,
        extra_query: Optional[Mapping[str, Any]] = None,
        extra_body: Optional[Mapping[str, Any]] = None,
        timeout: Union[float, httpx.Timeout, NotGiven, None] = NOT_GIVEN,
    ) -> LayrcakeResponse[TightenKeyPolicyResult]:
        """Tighten another key's policy (lower caps/limits, drop scopes).

        Requires control:manage. Loosening needs an owner in the console. Every external
        action needs a person's approval; autonomous_external_actions is deprecated,
        accepted only as false and always reported as false.

        `PATCH /v1/keys/{id}`

        Args:
            idempotency_key: Sent as the Idempotency-Key header. If omitted, the SDK
                generates one and reuses it on every automatic retry of this call.
        """
        return await self._transport.request(
            _ops.TIGHTEN_KEY_POLICY,
            path_params={"id": key_id},
            body={
                "name": name,
                "scopes": scopes,
                "monthly_spend_cap": monthly_spend_cap,
                "autonomous_external_actions": autonomous_external_actions,
                "autonomous_action_limits": autonomous_action_limits,
                "premium_offers": premium_offers,
                "premium_max_credits_per_call": premium_max_credits_per_call,
                "data_route": data_route,
            },
            extra_body=extra_body,
            idempotency_key=idempotency_key,
            extra_headers=extra_headers,
            extra_query=extra_query,
            timeout=timeout,
        )

